-- Lección: roma-imperio
insert into public.lessons (topic_id, title, body, position, published)
select id, 'El Imperio romano y su transformación', '[{"type":"section","title":"El principado: un poder sin nombre","text":"Augusto resolvió el problema que había matado a César: cómo ejercer un poder monárquico en una sociedad que odiaba el título de rey. Su solución fue no crear ningún cargo nuevo. Acumuló poderes republicanos existentes —imperium proconsular sobre las provincias con ejército, potestad tribunicia vitalicia, pontificado máximo— y se llamó a sí mismo princeps, «el primero», un término sin contenido jurídico.\n\nEl resultado fue un régimen deliberadamente ambiguo. El Senado seguía reuniéndose, los cónsules seguían eligiéndose, las formas republicanas continuaban intactas. Augusto proclamó en sus *Res Gestae* que había devuelto la República y que solo superaba a los demás en auctoritas, prestigio. Tácito, un siglo después, describió la operación con precisión brutal: los nombres de las magistraturas permanecieron, la sustancia cambió.\n\nLa ambigüedad tenía un coste: no existía una regla de sucesión. Augusto intentó resolverlo por adopción dentro de su familia, pero el sistema quedó estructuralmente indefinido. El año 69, con cuatro emperadores en doce meses, reveló lo que Tácito llamó el «secreto del imperio»: que se podía proclamar emperador fuera de Roma, y que quien decidía era el ejército.\n\nPese a ello, el sistema funcionó durante dos siglos con notable eficacia. El llamado siglo de los Antoninos (96-180 d. C.) combinó adopción de sucesores competentes, paz interior, expansión limitada y prosperidad comercial. Edward Gibbon lo consideró el periodo más feliz de la humanidad, juicio que hoy se matiza recordando que descansaba sobre la esclavitud, una fiscalidad regresiva y una desigualdad enorme.","textEso":"Augusto no se proclamó rey ni emperador: dijo que había restaurado la República. Mantuvo el Senado, las elecciones y los cargos de siempre, y se limitó a acumular en su persona los poderes que importaban: el mando del ejército, el control de las provincias ricas y el derecho de veto. Se llamó princeps, «el primero», y de ahí viene el nombre de principado. Fue una monarquía disfrazada de república, y funcionó precisamente porque nadie tuvo que admitir que la República había muerto.","textBachillerato":"El régimen creado por Augusto se sostiene en una ficción deliberada: la res publica restituta. Se conservan el Senado, las magistraturas y las asambleas, y el princeps se presenta como el primero entre iguales. Debajo de esa fachada acumula lo esencial: el imperium proconsular sobre las provincias con ejército, la potestad tribunicia con su veto e inviolabilidad, el control de la hacienda y el mando efectivo de las legiones.\n\nLa ambigüedad no es un defecto, es el mecanismo. Permitió que la aristocracia senatorial aceptara el nuevo orden sin renunciar a su prestigio, y que el sistema se presentara como continuidad y no como ruptura. Su punto débil es la sucesión: sin norma que la regule, cada transmisión depende de la adopción, del acuerdo del Senado o, cada vez más, del ejército. De ahí salen las crisis dinásticas del 68-69, del 193 y, convertida en norma, la anarquía del siglo III.","callout":"Las Res Gestae Divi Augusti, inscritas en bronce y copiadas por el imperio, son autobiografía política: hay que leerlas como propaganda cuidadosamente construida, no como memoria fiable."},{"type":"section","title":"Cómo funcionaba el imperio: fiscalidad, ejército y ciudades","text":"El Estado romano era, para su tamaño, asombrosamente ligero. Se calcula que la administración imperial contaba con unos pocos centenares de altos funcionarios para cincuenta millones de habitantes. La gestión ordinaria recaía en las ciudades: recaudación, orden público, obras, culto. El imperio funcionaba porque cooptó a las élites locales, que asumían cargos costosos a cambio de estatus, y en cuya lealtad descansaba todo el edificio.\n\nLa principal partida de gasto era el ejército: entre 300.000 y 400.000 hombres, que consumían la mayor parte del presupuesto. El grueso de los ingresos provenía de impuestos sobre la tierra y las personas en las provincias. Italia estuvo exenta del tributo directo hasta Diocleciano, una asimetría que revela el carácter originalmente extractivo del sistema.\n\nLa romanización se entendió durante mucho tiempo como difusión de una cultura superior hacia periferias receptivas. Esa lectura, formulada por Theodor Mommsen y sistematizada por Francis Haverfield en un contexto de imperialismo británico, ha sido revisada a fondo. Hoy se prefiere hablar de procesos de negociación e hibridación: las élites provinciales adoptaron selectivamente lengua, urbanismo y dioses romanos porque les daban acceso a poder y estatus, y en el proceso crearon formas mixtas —cultos sincréticos, onomástica doble, arquitectura adaptada— que no son ni indígenas ni romanas.\n\nLa cohesión económica fue notable. Los estudios de núcleos de hielo de Groenlandia muestran picos de contaminación por plomo en época altoimperial no igualados hasta la Revolución Industrial; los pecios mediterráneos alcanzan su máxima frecuencia entre el siglo I a. C. y el I d. C. El comercio de larga distancia movía grano egipcio y africano, aceite bético, vino itálico y galo, cerámica producida en serie.\n\nLa Constitutio Antoniniana de Caracalla (212 d. C.) concedió la ciudadanía a prácticamente todos los habitantes libres del imperio. Se ha discutido si fue una medida integradora o simplemente fiscal —ampliar la base de los impuestos que solo pagaban los ciudadanos—. Probablemente ambas: cerró un proceso de siglos y disolvió la distinción jurídica que había estructurado el mundo romano, sustituida por otra nueva entre honestiores y humiliores, es decir, entre acomodados y pobres.","textEso":"El imperio se sostenía sobre tres cosas. Un ejército profesional de unos 300.000 hombres, estacionado en las fronteras, que cobraba un sueldo y recibía tierras al licenciarse. Un sistema de impuestos que gravaba sobre todo la tierra y que pagaban las provincias. Y las ciudades: Roma no administraba directamente a sus millones de habitantes, sino que dejaba que las élites locales gobernasen sus ciudades y recaudasen, a cambio de prestigio y de la ciudadanía romana. Una red de calzadas y puertos lo mantenía todo conectado.","textBachillerato":"El Imperio funcionaba con una administración central asombrosamente pequeña: unos pocos centenares de altos funcionarios para decenas de millones de habitantes. La clave está en la delegación. Las ciudades, con sus élites locales organizadas en senados municipales, gobernaban y recaudaban; a cambio recibían prestigio, cargos y la ciudadanía romana, extendida finalmente a casi todos los libres en 212.\n\nEl segundo pilar es el ejército: unos 300.000 hombres profesionales, estacionados en las fronteras, con sueldo y asentamiento al licenciarse. Absorbía la mayor parte del presupuesto, y eso explica la estructura fiscal, centrada en el impuesto sobre la tierra que pagaban las provincias. El tercero es la infraestructura: calzadas, puertos y una moneda común que permitieron un comercio de larga distancia cuyo volumen no se recuperaría en Europa hasta la Edad Moderna. Un sistema eficiente pero rígido: cualquier aumento sostenido del gasto militar solo podía cubrirse subiendo la presión fiscal.","callout":null},{"type":"section","title":"La crisis del siglo III","text":"Entre 235 y 284 d. C. el imperio estuvo cerca del colapso. Hubo más de veinte emperadores reconocidos y numerosos usurpadores; casi ninguno murió de muerte natural. Las legiones proclamaban candidatos y los deponían, y la guerra civil se hizo endémica.\n\nLa presión exterior aumentó simultáneamente en dos frentes. En el Rin y el Danubio, confederaciones germánicas más grandes y mejor organizadas —alamanes, francos, godos— sustituyeron a las tribus dispersas de época altoimperial. En Oriente, el Imperio sasánida, surgido en 224, era un adversario estatal de primer orden: en 260 capturó vivo al emperador Valeriano, humillación sin precedentes.\n\nA ello se sumó una crisis monetaria de manual. Para pagar al ejército, los emperadores redujeron el contenido de plata del denario, que pasó de un 90 % en época de Augusto a menos del 5 % a mediados del siglo III. El resultado fue una inflación descontrolada, la vuelta parcial a pagos en especie y la ruptura de circuitos comerciales. La peste de Cipriano, hacia 249-262, añadió mortalidad masiva.\n\nEl imperio llegó a fragmentarse: el Imperio galo (260-274) y el reino de Palmira bajo Zenobia funcionaron como Estados independientes durante más de una década. Que se reunificara es tan significativo como que se rompiera.\n\nLa recuperación llegó con Aureliano y, sobre todo, con Diocleciano. Este dividió el poder en la tetrarquía —dos augustos y dos césares, con sucesión planificada—, duplicó el número de provincias para reducir el poder de cada gobernador, separó mando militar y administración civil, reformó la fiscalidad con un sistema de unidades de tierra y de trabajo (iugatio-capitatio) e intentó frenar la inflación con un edicto de precios máximos que fracasó. El Estado resultante era mucho más grande, más caro y más coactivo que el altoimperial.","textEso":"En el siglo III todo se torció a la vez: presión de pueblos germánicos y persas en las fronteras, emperadores nombrados y asesinados por sus propios soldados —más de veinte en cincuenta años—, peste, y una moneda que perdió casi todo su contenido de plata y provocó una inflación enorme. El imperio no se hundió: Diocleciano y Constantino lo reconstruyeron, pero con otra forma. Más funcionarios, más impuestos, un ejército mayor y un emperador ya abiertamente absoluto, alejado de Roma y rodeado de ceremonial.","textBachillerato":"La crisis del siglo III fue una acumulación de tensiones simultáneas. En el exterior, confederaciones germánicas más cohesionadas y un Imperio sasánida agresivo que llegó a capturar a un emperador romano. En el interior, más de veinte emperadores en cincuenta años, casi todos proclamados y eliminados por sus tropas, y secesiones territoriales como el Imperio de las Galias o Palmira.\n\nA eso se sumó una peste de gran mortalidad y una crisis monetaria: el denario perdió casi todo su contenido de plata y la inflación desorganizó el comercio y la fiscalidad, que pasó a cobrarse en especie. La respuesta fue una reconstrucción profunda con Diocleciano y Constantino: división administrativa en más provincias y diócesis, separación entre mando militar y civil, ejército mayor con unidades móviles, reforma monetaria y un emperador ya abiertamente absoluto, con corte ceremonial y capital fuera de Roma. El Imperio sobrevive, pero el principado de Augusto ha desaparecido.","callout":"El Edicto de Precios Máximos de 301 fijaba tarifas para más de mil productos y servicios, con pena de muerte por incumplimiento. Es la fuente más rica sobre la economía tardorromana y, a la vez, el testimonio de su fracaso: los bienes desaparecieron del mercado."},{"type":"section","title":"Cristianización: de secta perseguida a religión de Estado","text":"El cristianismo era, en el siglo I, un movimiento judío minoritario. Su expansión inicial se apoyó en las redes urbanas del imperio, en la lengua griega común y en las rutas comerciales. Las persecuciones fueron episódicas y menos masivas de lo que sugiere la tradición martirial: la de Decio (250) y la de Diocleciano (303-311) fueron las únicas de alcance imperial y sistemático.\n\nLo que resulta históricamente notable no es la persecución, sino el crecimiento. Rodney Stark ha estimado, a partir de una tasa de crecimiento sostenido en torno al 3,4 % anual, que los cristianos pasarían de unos pocos miles a comienzos del siglo II a varios millones a comienzos del IV: en torno al 10 % de la población en vísperas de Constantino. El cálculo es una modelización discutida, pero la magnitud del orden se acepta.\n\nLas explicaciones del éxito combinan varios factores: una comunidad con asistencia mutua efectiva —viudas, huérfanos, enfermos, entierros—, una doctrina de salvación universal accesible sin requisitos de nacimiento ni de riqueza, una posición favorable entre las mujeres, y una exclusividad que, a diferencia de los cultos paganos, impedía la vuelta atrás.\n\nLa conversión de Constantino cambió la escala. El Edicto de Milán (313) estableció la tolerancia; el emperador financió basílicas, concedió privilegios fiscales al clero y convocó el concilio de Nicea (325) para resolver la disputa arriana sobre la naturaleza de Cristo. La intervención imperial en cuestiones doctrinales inauguró una relación de dependencia mutua entre Iglesia e Imperio que marcaría siglos.\n\nCon el Edicto de Tesalónica (380), Teodosio hizo del cristianismo niceno la religión oficial y, en la década siguiente, prohibió los cultos tradicionales. La relación se invirtió por completo en menos de un siglo: la religión perseguida se convirtió en perseguidora. El episodio de Ambrosio de Milán obligando a Teodosio a hacer penitencia pública tras la matanza de Tesalónica (390) muestra que la Iglesia había adquirido capacidad de imponer límites al poder imperial.","textEso":"El cristianismo empezó siendo una religión minoritaria y perseguida a rachas, nunca de forma continua. Lo que le dio ventaja fue su organización: comunidades con obispos, ayuda mutua, y una promesa de salvación abierta a todos sin distinción de origen o clase. En 313 Constantino lo legalizó, y en 380 Teodosio lo convirtió en religión oficial del Estado. En menos de un siglo la Iglesia pasó de perseguida a perseguidora de los cultos antiguos.","textBachillerato":"El cristianismo creció durante casi tres siglos como minoría. Las persecuciones fueron episódicas y locales más que sistemáticas: las generales, bajo Decio y Diocleciano, son tardías y breves. Lo que explica su expansión es menos el martirio que la organización: comunidades estructuradas con obispos, redes de asistencia a pobres, viudas y enfermos, y un mensaje de salvación accesible a cualquiera con independencia de origen, sexo o condición jurídica.\n\nEl giro llega con Constantino: el edicto de Milán de 313 establece la tolerancia, y el propio emperador convoca el concilio de Nicea en 325, interviniendo en la definición del dogma. En 380 Teodosio hace del cristianismo niceno la religión oficial y prohíbe los cultos tradicionales. El cambio de posición es radical y rápido: en menos de un siglo, la Iglesia pasa de perseguida a disponer del respaldo coactivo del Estado. Que esa alianza fuera una victoria o una captura del cristianismo por el poder imperial es una discusión abierta desde entonces.","callout":null},{"type":"section","title":"El siglo V en Occidente: qué ocurrió realmente","text":"La imagen de hordas bárbaras derribando un imperio no resiste el examen. Los grupos que entraron en el imperio eran demográficamente pequeños —las estimaciones para los vándalos que pasaron a África en 429 rondan las 80.000 personas, incluidas mujeres y niños—, estaban parcialmente romanizados, buscaban tierras y estatus dentro del sistema y a menudo servían como tropas federadas del propio ejército romano.\n\nLa secuencia es más bien de erosión fiscal. Cada territorio perdido reducía los ingresos; con menos ingresos había menos ejército; con menos ejército se perdían más territorios. La pérdida de África en 439, la provincia más rica y granero de Roma, fue probablemente el golpe decisivo. Chris Wickham y Bryan Ward-Perkins han insistido en este mecanismo acumulativo.\n\nLa política interna agravó el proceso. El poder efectivo pasó a manos de generales —Estilicón, Aecio, Ricimero—, con frecuencia de origen bárbaro, que hacían y deshacían emperadores. Roma dejó de ser capital, sustituida por Milán y después por Rávena. Cuando en 476 Odoacro depuso a Rómulo Augústulo, no proclamó un nuevo imperio: envió las insignias imperiales a Constantinopla y gobernó Italia como representante nominal del emperador de Oriente. Los contemporáneos no percibieron el fin de nada.\n\nMientras tanto, el Imperio de Oriente sobrevivió otros mil años. Esa asimetría es el mejor argumento contra las explicaciones globales: cualquier causa que se invoque —cristianismo, decadencia moral, plomo en las cañerías, presión bárbara— debería explicar también por qué Oriente resistió. Oriente tenía fronteras más cortas y defendibles, una base fiscal más rica —Egipto, Siria— y una capital inexpugnable.\n\nLas consecuencias materiales en Occidente sí fueron severas. Ward-Perkins ha documentado, a partir de la cultura material, una caída drástica en la calidad y difusión de la cerámica, en el tamaño del ganado, en la circulación monetaria y en el uso de tejas: indicadores de un descenso general del nivel de vida y de la complejidad económica. Su libro *La caída de Roma y el fin de la civilización* (2005) reaccionó explícitamente contra las lecturas que presentan el periodo como una transición amable.","textEso":"El año 476 suele darse como el fin del Imperio romano de Occidente, pero lo que pasó ese año fue menor: un general depuso a un emperador que ya no gobernaba casi nada. El proceso real fue más largo y más gris. Los pueblos germánicos no llegaron solo como invasores: muchos entraron como soldados federados, pactados, y acabaron controlando territorios desde dentro. Al mismo tiempo el Estado se quedó sin dinero para pagar su ejército. En Oriente, en cambio, el imperio siguió en pie mil años más.","textBachillerato":"La fecha de 476 es una convención establecida mucho después: Odoacro depuso a Rómulo Augústulo, un emperador que ya no controlaba más que parte de Italia, y no se proclamó emperador sino que remitió las insignias a Constantinopla. Ningún contemporáneo describió el suceso como el fin del Imperio.\n\nEl proceso real combina varios factores. Los pueblos germánicos entraron en buena medida como federados pactados y fueron asentados dentro de las fronteras, de modo que el ejército romano occidental acabó estando compuesto y mandado por ellos. A la vez, la pérdida de provincias fiscales —el norte de África, con su grano, es decisiva— dejó al Estado sin recursos para pagar a sus propias tropas. La discusión historiográfica oscila entre quienes hablan de caída violenta y quienes hablan de transformación y continuidad; el dato que obliga a matizar cualquier relato catastrofista es que el Imperio de Oriente no solo no cayó, sino que duró otros mil años.","callout":"El propio término «bárbaro» procede del griego y designaba a quien no hablaba griego. Aplicado sin más a los pueblos del siglo V, importa una imagen de otredad radical que las fuentes arqueológicas no sostienen."},{"type":"section","title":"El legado: derecho, lengua y una idea de imperio","text":"La aportación romana más duradera no fue política, sino jurídica. El derecho romano desarrolló categorías —propiedad, contrato, obligación, persona jurídica, buena fe— con un nivel de abstracción que ninguna otra tradición antigua alcanzó. Su recopilación en el *Corpus Iuris Civilis* de Justiniano (528-534) y su redescubrimiento en Bolonia en el siglo XI lo convirtieron en la base de los sistemas jurídicos continentales europeos y latinoamericanos.\n\nLa huella lingüística es igualmente estructural. El latín vulgar de las provincias occidentales derivó en las lenguas romances: castellano, portugués, catalán, gallego, francés, occitano, italiano, rumano. Y el latín culto siguió siendo la lengua de la administración, la Iglesia, el derecho y la ciencia europeos hasta el siglo XVIII.\n\nLa idea de imperio como orden universal legítimo sobrevivió a la desaparición del Estado que la había encarnado. Se reclamó en el imperio carolingio, en el Sacro Imperio Romano Germánico, en la Rusia que se llamó a sí misma «tercera Roma», y en la iconografía política de las monarquías modernas. La palabra káiser y la palabra zar derivan ambas de César.\n\nConviene, sin embargo, resistir la tentación de leer Roma como antecesora directa de nada. Fue una sociedad esclavista en la que quizá entre un 10 % y un 20 % de la población carecía de personalidad jurídica; su expansión implicó exterminios documentados por sus propios autores, como el de la Galia narrado por César; y su prosperidad descansaba en una extracción fiscal sobre provincias sometidas. El interés histórico de Roma no está en su ejemplaridad, sino en que es el caso mejor documentado de cómo se construye, se mantiene y se deshace un Estado de escala continental.","textEso":"Lo que Roma dejó sigue en uso. El derecho romano es la base de los códigos civiles de casi toda Europa y de América Latina. El latín se transformó en español, francés, italiano, portugués y rumano. La Iglesia heredó su organización territorial y su lengua. Y la propia idea de imperio —un poder universal que unifica pueblos distintos bajo una sola ley— fue reclamada después por Carlomagno, por el Sacro Imperio, por los zares y por Napoleón.","textBachillerato":"El legado romano es menos el de los monumentos que el de las estructuras. El derecho romano, sistematizado en la compilación de Justiniano, se recuperó en las universidades medievales desde el siglo XII y está en la base de los códigos civiles de la Europa continental y de América Latina: conceptos como contrato, propiedad, persona jurídica o responsabilidad vienen de ahí.\n\nEl latín hablado se fragmentó en las lenguas romances, y el latín culto siguió siendo la lengua de la administración, la ciencia y la Iglesia hasta bien entrada la Edad Moderna. La Iglesia heredó la organización territorial imperial, con las diócesis, y su lengua. Y la idea misma de imperio —un poder universal que reúne pueblos distintos bajo una ley común— fue reclamada sucesivamente por Carlomagno, el Sacro Imperio, los zares rusos, el imperio otomano y Napoleón. Que todos ellos quisieran presentarse como herederos de Roma dice más sobre la potencia de esa idea que cualquier ruina.","callout":null},{"type":"concepts","items":[{"term":"Princeps","definition":"«El primero»: título sin contenido jurídico con el que Augusto disimuló un poder monárquico."},{"term":"Auctoritas","definition":"Prestigio y ascendiente moral. Augusto afirmó superar a los demás solo en esto, no en poder formal."},{"term":"Potestad tribunicia","definition":"Poder vitalicio de veto e inviolabilidad que el emperador acumulaba sin ser tribuno."},{"term":"Constitutio Antoniniana","definition":"Edicto de Caracalla (212) que concedió la ciudadanía a casi todos los habitantes libres del imperio."},{"term":"Honestiores / humiliores","definition":"Nueva distinción jurídica tras 212: acomodados frente a pobres, con penas distintas por el mismo delito."},{"term":"Tetrarquía","definition":"Sistema de Diocleciano con dos augustos y dos césares para repartir el gobierno y planificar la sucesión."},{"term":"Iugatio-capitatio","definition":"Sistema fiscal tardorromano basado en unidades de tierra y de trabajo."},{"term":"Limes","definition":"Sistema fronterizo fortificado, más zona de control y contacto que muralla estanca."},{"term":"Foederati","definition":"Pueblos asentados dentro del imperio con obligación de aportar tropas bajo sus propios jefes."},{"term":"Romanización","definition":"Antes, difusión cultural unidireccional; hoy se entiende como negociación e hibridación entre Roma y las élites locales."},{"term":"Corpus Iuris Civilis","definition":"Compilación jurídica de Justiniano (528-534), base del derecho continental europeo tras su redescubrimiento medieval."}]},{"type":"debates","items":[{"question":"¿Por qué cayó el Imperio romano de Occidente?","positions":[{"school":"Decadencia interna (Gibbon, 1776-1789)","argument":"La pérdida de virtud cívica, el peso del ejército mercenario y, señaladamente, el cristianismo, que habría desviado energías hacia el más allá y debilitado el espíritu militar y la lealtad al Estado."},{"school":"Erosión fiscal y militar (Ward-Perkins, Heather)","argument":"La pérdida de provincias redujo los ingresos, lo que redujo el ejército, lo que provocó nuevas pérdidas. La caída de África en 439 fue decisiva. La presión externa, real y creciente, actuó sobre un Estado fiscalmente estrangulado."},{"school":"Transformación, no caída (Brown, Goffart)","argument":"No hubo colapso sino una larga transición: los reinos germánicos se instalaron dentro de estructuras romanas, conservaron la administración, el latín y la Iglesia, y la Antigüedad tardía fue una época de creatividad religiosa y cultural propia."}],"state":"El paradigma de la «transformación» dominó los años ochenta y noventa; Ward-Perkins y Heather reaccionaron aportando evidencia material de un descenso severo del nivel de vida en Occidente. Hoy se acepta que hubo a la vez continuidad institucional y una regresión económica real, con enorme variación regional. La supervivencia de Oriente sigue siendo el mejor test de cualquier explicación."},{"question":"¿Qué fue la romanización?","positions":[{"school":"Difusión cultural (Mommsen, Haverfield)","argument":"Roma habría llevado urbanismo, derecho, lengua y civilización a pueblos menos desarrollados, que los adoptaron por su superioridad evidente. Modelo formulado en pleno auge del imperialismo europeo."},{"school":"Negociación e hibridación (Woolf, Mattingly)","argument":"Las élites provinciales adoptaron selectivamente elementos romanos porque daban acceso a poder y estatus, generando formas mixtas. Hubo también resistencia, indiferencia y desigualdad: la experiencia de la conquista fue muy distinta para una élite gala y para un campesino o un esclavo."}],"state":"El modelo difusionista está descartado como marco explicativo. Se prefieren conceptos como «identidades discrepantes» (Mattingly) que reconocen experiencias divergentes dentro de una misma provincia."},{"question":"¿Fue la Constitutio Antoniniana una medida integradora o fiscal?","positions":[{"school":"Motivo fiscal (Dión Casio, contemporáneo)","argument":"Caracalla buscaba ampliar la base de los impuestos que solo gravaban a los ciudadanos, en particular el de sucesiones. Un historiador contemporáneo se lo atribuye explícitamente."},{"school":"Culminación integradora","argument":"Cerraba un proceso secular de extensión progresiva de la ciudadanía y respondía a que la distinción entre ciudadano y peregrino había perdido sentido práctico en un imperio ya homogeneizado."}],"state":"Se admiten ambos motivos como compatibles. Lo más relevante es su consecuencia: la ciudadanía dejó de ser un privilegio distintivo y fue sustituida por la división socioeconómica entre honestiores y humiliores."}]},{"type":"timeline","items":[{"date":"27 a. C.","event":"Octavio recibe el nombre de Augusto: nace el principado."},{"date":"9 d. C.","event":"Desastre de Teutoburgo; el Rin queda como frontera."},{"date":"69 d. C.","event":"Año de los cuatro emperadores: el ejército decide la sucesión."},{"date":"117 d. C.","event":"Máxima extensión territorial bajo Trajano."},{"date":"122 d. C.","event":"Inicio del muro de Adriano: de la expansión a la consolidación."},{"date":"165–180 d. C.","event":"Peste antonina; mortalidad estimada entre el 10 % y el 25 %."},{"date":"212 d. C.","event":"Constitutio Antoniniana: ciudadanía a casi todos los habitantes libres."},{"date":"235–284 d. C.","event":"Crisis del siglo III: anarquía militar, invasiones e inflación."},{"date":"284–305 d. C.","event":"Diocleciano: tetrarquía, reforma fiscal y administrativa."},{"date":"313 d. C.","event":"Edicto de Milán: tolerancia del cristianismo."},{"date":"325 d. C.","event":"Concilio de Nicea."},{"date":"380 d. C.","event":"Edicto de Tesalónica: el cristianismo niceno, religión oficial."},{"date":"378 d. C.","event":"Adrianópolis: derrota y muerte del emperador Valente ante los godos."},{"date":"395 d. C.","event":"División administrativa definitiva entre Oriente y Occidente."},{"date":"410 d. C.","event":"Saqueo de Roma por Alarico."},{"date":"476 d. C.","event":"Odoacro depone a Rómulo Augústulo: fin convencional del Imperio de Occidente."}]},{"type":"sources","items":[{"author":"Augusto","title":"Res Gestae Divi Augusti","year":"14 d. C.","kind":"primaria","note":"Autobiografía política inscrita en bronce y copiada por el imperio. Propaganda, no memoria fiable."},{"author":"Tácito","title":"Anales; Historias; Germania","year":"c. 110–120 d. C.","kind":"primaria","note":"Análisis crítico del principado desde la perspectiva senatorial. Formula el «secreto del imperio»."},{"author":"Plinio el Joven","title":"Cartas, libro X","year":"c. 111 d. C.","kind":"primaria","note":"Correspondencia con Trajano: administración provincial y primer testimonio oficial sobre los cristianos."},{"author":"Diocleciano","title":"Edicto de Precios Máximos","year":"301 d. C.","kind":"primaria","note":"Tarifas para más de mil bienes y servicios. Fuente central sobre la economía tardorromana."},{"author":"Amiano Marcelino","title":"Res Gestae","year":"c. 390 d. C.","kind":"primaria","note":"Última gran historia latina; narra Adrianópolis como testigo cercano."},{"author":"Agustín de Hipona","title":"La ciudad de Dios","year":"413–426","kind":"primaria","note":"Respuesta al saqueo de 410 y a la acusación de que el cristianismo había causado la ruina de Roma."},{"author":"Edward Gibbon","title":"The History of the Decline and Fall of the Roman Empire","year":"1776–1789","kind":"estudio","note":"Obra fundacional del debate; responsabiliza en parte al cristianismo."},{"author":"Peter Brown","title":"The World of Late Antiquity","year":"1971","kind":"estudio","note":"Funda el paradigma de la Antigüedad tardía como transformación creativa y no como decadencia."},{"author":"Bryan Ward-Perkins","title":"The Fall of Rome and the End of Civilization","year":"2005","kind":"estudio","note":"Reacción contra el paradigma de la transformación, con evidencia arqueológica de regresión material."},{"author":"Peter Heather","title":"The Fall of the Roman Empire: A New History","year":"2005","kind":"estudio","note":"Subraya el papel real de la presión externa sobre un Estado fiscalmente debilitado."},{"author":"Greg Woolf","title":"Becoming Roman: The Origins of Provincial Civilization in Gaul","year":"1998","kind":"estudio","note":"Modelo de romanización como negociación e hibridación."},{"author":"Chris Wickham","title":"Framing the Early Middle Ages","year":"2005","kind":"estudio","note":"Comparación regional sistemática de la transición entre el mundo romano y el medieval."}]},{"type":"images","items":[{"src":"/img/roma-imperio/portada.jpg","alt":"El Coliseo de Roma visto desde el exterior, con sus arcadas superpuestas y la fachada parcialmente derruida","width":1200,"height":704,"role":"portada","caption":"El anfiteatro Flavio, inaugurado en el año 80.","author":"Diliff","title":"Colosseum in Rome, Italy - April 2007","year":"2007","source":"Wikimedia Commons","license":"CC BY-SA 2.5","url":"https://commons.wikimedia.org/wiki/File:Colosseum_in_Rome%2C_Italy_-_April_2007.jpg"},{"src":"/img/roma-imperio/augusto.jpg","alt":"Estatua de mármol de un hombre con coraza decorada, brazo derecho alzado y un pequeño amorcillo a sus pies","width":1200,"height":1800,"role":"figura","section":0,"caption":"Augusto de Prima Porta. Se presenta como general victorioso y descendiente de Venus, nunca como rey: el principado es un poder real sin nombre legal.","author":"Till Niermann","title":"Statue-Augustus","year":"2007","source":"Wikimedia Commons","license":"Public domain","url":"https://commons.wikimedia.org/wiki/File:Statue-Augustus.jpg"},{"src":"/img/roma-imperio/pont-du-gard.jpg","alt":"Acueducto romano de tres pisos de arcos de piedra cruzando un río entre laderas boscosas","width":1200,"height":463,"role":"figura","section":1,"caption":"El Pont du Gard, en la Galia Narbonense, del siglo I. El agua caía 17 metros en 50 kilómetros: la obra pública es la cara visible de la fiscalidad imperial.","author":"Benh LIEU SONG ( Flickr )","title":"Pont du Gard BLS","year":"2014","source":"Wikimedia Commons","license":"CC BY-SA 3.0","url":"https://commons.wikimedia.org/wiki/File:Pont_du_Gard_BLS.jpg"},{"src":"/img/roma-imperio/arco-constantino.jpg","alt":"Arco triunfal de tres vanos con relieves y estatuas sobre las columnas, visto de frente","width":1200,"height":900,"role":"figura","section":3,"caption":"Arco de Constantino, 315. Buena parte de sus relieves se arrancó de monumentos anteriores: la Roma del siglo IV se cita a sí misma porque ya no puede igualarse.","author":"Wknight94","title":"Arch of Constantine (Rome)","year":"2008","source":"Wikimedia Commons","license":"CC BY-SA 3.0","url":"https://commons.wikimedia.org/wiki/File:Arch_of_Constantine_(Rome).jpg"}]}]'::jsonb, 0, true
from public.topics where slug = 'roma-imperio'
