  title = excluded.title, body = excluded.body, published = excluded.published;

-- Lección: roma-republica
insert into public.lessons (topic_id, title, body, position, published)
select id, 'Roma: la República', '[{"type":"section","title":"El problema de las fuentes de la Roma arcaica","text":"Casi todo lo que la tradición cuenta sobre los orígenes de Roma —Rómulo, los siete reyes, la expulsión de Tarquinio el Soberbio en 509 a. C.— procede de autores que escriben cuatro o cinco siglos después: Tito Livio y Dionisio de Halicarnaso, ambos de época augústea. No son testigos, sino recopiladores de una tradición ya elaborada.\n\nEsa tradición fue moldeada retrospectivamente. Las familias aristocráticas conservaban elogios fúnebres y listas de magistrados que tendían a exagerar sus méritos e insertar antepasados en episodios gloriosos. Además, los relatos de la monarquía y de la primera República están construidos con categorías políticas del siglo I a. C.: proyectan hacia atrás conflictos y conceptos contemporáneos a sus autores.\n\nLa arqueología ha corregido y a veces confirmado partes del relato. Muestra un núcleo urbano organizado en el Palatino y el Foro ya en el siglo VII a. C., con un fuerte influjo etrusco y griego, lo que contradice la imagen de una aldea de pastores. Pero no permite verificar nombres ni fechas concretas.\n\nLa consecuencia metodológica es clara: para el periodo anterior al siglo IV a. C. conviene leer la tradición como memoria cultural —lo que los romanos creían sobre sí mismos y les servía para justificar su orden político— más que como crónica. Que sea memoria y no crónica no la hace inútil: explica cómo Roma se pensaba a sí misma.","textEso":null,"textBachillerato":"Todo lo que se cuenta de la Roma de los reyes y de los primeros siglos republicanos procede de autores que escriben cuatrocientos o quinientos años después, como Tito Livio. Roma no tenía historiografía propia hasta el siglo III a. C., y el incendio de la ciudad por los galos en 390 a. C. destruyó buena parte de los registros anteriores.\n\nEso significa que el relato tradicional —la loba, Rómulo, la expulsión de Tarquinio, Cincinato volviendo al arado— es material construido para justificar los valores de la Roma posterior, no crónica. La arqueología permite corregirlo en lo esencial: hubo monarquía, hubo fuerte influencia etrusca y la ciudad era más rica y urbana de lo que sugiere el mito de los orígenes humildes. Conviene tenerlo presente antes de citar cualquier anécdota de la Roma arcaica.","callout":"El relato de Lucrecia y la expulsión de los reyes cumple una función precisa: fundar la República sobre el rechazo a la arbitrariedad personal. El odio al título de rex duró hasta César, y contribuyó a su muerte."},{"type":"section","title":"La constitución republicana: un equilibrio sin texto","text":"Roma no tuvo constitución escrita. Su sistema era un conjunto de instituciones, leyes y costumbres —el mos maiorum, la «costumbre de los antepasados»— que evolucionó por acumulación y precedente. Polibio, historiador griego rehén en Roma, la describió en el libro VI de sus *Historias* como una constitución mixta que combinaba monarquía (los cónsules), aristocracia (el Senado) y democracia (las asambleas), y atribuyó a ese equilibrio la estabilidad romana.\n\nLas magistraturas eran colegiadas, anuales y gratuitas. Dos cónsules dirigían el Estado y el ejército, con derecho de veto mutuo; los pretores administraban justicia; los cuestores gestionaban finanzas; los ediles, la ciudad; y los censores, cada cinco años, revisaban las listas de ciudadanos y del Senado y vigilaban las costumbres. El cursus honorum fijaba el orden y las edades mínimas de esa carrera. En emergencias podía nombrarse un dictador con poderes plenos por un máximo de seis meses.\n\nEl Senado, integrado por exmagistrados y vitalicio, no legislaba formalmente: emitía senadoconsultos, opiniones de enorme peso moral y práctico. Controlaba de hecho las finanzas, la política exterior y la asignación de provincias y mandos. Era el órgano de continuidad frente a magistrados que cambiaban cada año.\n\nLas asambleas votaban leyes y elegían magistrados, pero su diseño limitaba el peso de los pobres. Los comicios centuriados, organizados por clases de fortuna, distribuían el voto por centurias y no por cabeza, y las centurias de los más ricos votaban primero: cuando se alcanzaba la mayoría, la votación se detenía y las clases inferiores a menudo ni llegaban a pronunciarse. Que las asambleas fueran soberanas en teoría no significa que el pueblo decidiera en la práctica.\n\nLa verdadera argamasa del sistema era la clientela: una relación asimétrica y hereditaria entre un patrono, que proporcionaba protección jurídica y ayuda material, y sus clientes, que le debían apoyo político, acompañamiento público y voto. La política romana funcionaba sobre esas redes personales mucho más que sobre programas.","textEso":"La República romana no tuvo constitución escrita: era un reparto de poder entre tres piezas. Los magistrados, elegidos cada año y siempre por parejas para que se vigilaran entre sí, con los cónsules a la cabeza. El Senado, una asamblea de antiguos magistrados que no hacía leyes pero controlaba el dinero y la política exterior y cuyo prestigio pesaba más que cualquier norma. Y las asambleas del pueblo, que votaban leyes y elegían cargos, aunque con un sistema de voto por grupos que favorecía a los ricos.","textBachillerato":"La República no tuvo texto constitucional. Su funcionamiento se basaba en la interacción de tres elementos: magistraturas anuales y colegiadas, con el veto mutuo entre colegas y la prohibición de repetir; el Senado, cuerpo de antiguos magistrados sin potestad legislativa formal pero con control efectivo de la hacienda, las provincias y la política exterior; y las asambleas populares, que aprobaban leyes y elegían magistrados.\n\nDos rasgos la definen. El primero es el voto por grupos: no se contaban personas sino centurias o tribus, y la ordenación por riqueza hacía que las clases altas votasen antes y a menudo decidiesen el resultado. El segundo es el peso de lo no escrito: la auctoritas del Senado y la red de clientelas pesaban más que cualquier norma. Polibio la presentó como una constitución mixta equilibrada, lectura que influyó en el constitucionalismo moderno, pero que describe el sistema tal como funcionaba en su mejor momento y no su práctica real.","callout":null},{"type":"section","title":"El conflicto de los órdenes","text":"Durante los dos primeros siglos de la República, la plebe —el conjunto de ciudadanos no pertenecientes a las familias patricias— luchó por acceder a las magistraturas, al sacerdocio y a la tierra pública, y por protegerse del abuso jurídico y del endeudamiento.\n\nSu arma más eficaz fue la secesión: retirarse en masa fuera de la ciudad y negarse a combatir. Roma, en guerra permanente con sus vecinos, no podía prescindir de sus soldados. La primera secesión (494 a. C.) arrancó la creación del tribunado de la plebe, magistratura con dos rasgos excepcionales: la sacrosanctitas —quien agrediera a un tribuno quedaba maldito y podía ser muerto impunemente— y el derecho de intercessio, que permitía vetar cualquier acto de un magistrado.\n\nLa Ley de las Doce Tablas (451-450 a. C.) fijó por escrito el derecho. Su contenido no era favorable a la plebe en muchos puntos —mantenía la ejecución sobre la persona del deudor y prohibía inicialmente los matrimonios mixtos—, pero eliminó el monopolio patricio sobre el conocimiento de la norma, que hasta entonces era interpretada oralmente por los pontífices.\n\nEl proceso culminó en tres etapas: las leyes Licinias-Sextias (367 a. C.) abrieron el consulado a los plebeyos; la lex Poetelia (326 a. C.) abolió el nexum, la servidumbre por deudas; y la lex Hortensia (287 a. C.) estableció que los plebiscitos —acuerdos de la asamblea de la plebe— obligaban a todo el pueblo, incluidos los patricios.\n\nEl resultado no fue igualdad, sino sustitución de una élite por otra más amplia. Se formó la nobilitas patricio-plebeya: familias que habían alcanzado el consulado y que monopolizaron los cargos durante siglos. Un homo novus —el primero de su familia en llegar al consulado, como Cicerón— era una rareza señalada. La apertura formal de las magistraturas convivió con un cierre sociológico muy estricto.","textEso":"Durante los dos primeros siglos la República vivió un conflicto interno entre patricios, las familias aristocráticas que monopolizaban los cargos, y plebeyos, todos los demás. Los plebeyos tenían un arma: negarse a acudir al ejército. Con esa presión consiguieron magistrados propios, los tribunos de la plebe, que podían bloquear cualquier decisión; leyes escritas, las Doce Tablas; y acceso a los cargos. El resultado no fue la igualdad, sino una nueva élite mixta de ricos patricios y plebeyos.","textBachillerato":"El conflicto de los órdenes enfrentó durante más de dos siglos a los patricios, que monopolizaban sacerdocios y magistraturas, con los plebeyos. El instrumento de presión plebeyo fue la secessio: retirarse de la ciudad y negarse a servir en el ejército, algo devastador para una comunidad en guerra permanente.\n\nLos resultados fueron acumulativos: tribunos de la plebe con derecho de veto e inviolabilidad personal, la fijación escrita del derecho en las Doce Tablas hacia 450 a. C., el acceso plebeyo al consulado y, con la Lex Hortensia de 287 a. C., la validez general de los acuerdos de la asamblea plebeya. Conviene no leerlo como una conquista democrática: el beneficio se concentró en las familias plebeyas ricas, que se integraron con las patricias formando una nobilitas mixta. La desigualdad económica no se tocó, y reaparecerá con fuerza en el siglo II a. C.","callout":"La sacrosanctitas del tribuno era una garantía religiosa, no jurídica. Cuando en 133 a. C. Tiberio Graco fue asesinado siendo tribuno, se rompió un tabú que había sostenido el sistema durante tres siglos."},{"type":"section","title":"La expansión mediterránea y sus mecanismos","text":"Roma sometió Italia entre los siglos IV y III a. C. mediante una combinación de guerra y de ingeniería jurídica. En lugar de reducir a los vencidos a súbditos uniformes, creó un mosaico de estatutos: colonias latinas, municipios con distintos grados de ciudadanía, aliados (socii) obligados a aportar tropas pero no impuestos. Esa flexibilidad, que integraba a las élites locales en el sistema, explica la resistencia romana a las derrotas: cuando Aníbal esperaba que Italia se sublevara, la mayor parte de los aliados permaneció fiel.\n\nLas guerras púnicas transformaron a Roma. La primera (264-241 a. C.) la obligó a construir una flota desde cero y le dio Sicilia, su primera provincia. La segunda (218-201 a. C.) fue existencial: Aníbal cruzó los Alpes, destruyó tres ejércitos consulares y aniquiló en Cannas (216 a. C.) a unos 50.000 romanos en una sola jornada. Roma sobrevivió por su capacidad de reponer ejércitos y por la estrategia de desgaste de Fabio Máximo, y ganó cuando Escipión llevó la guerra a África.\n\nA partir de 200 a. C., la expansión hacia el este fue rápida: Macedonia, Grecia, Asia Menor. En 146 a. C. Roma destruyó Cartago y Corinto en el mismo año. Polibio, testigo de la caída de Cartago, se planteó explícitamente la pregunta que da sentido a su obra: cómo en menos de cincuenta y tres años casi todo el mundo conocido quedó bajo dominio romano.\n\nLa explicación del imperialismo romano se ha discutido intensamente. La lectura tradicional, apoyada en las propias fuentes romanas, hablaba de un «imperialismo defensivo»: Roma habría hecho guerras justas, provocada siempre por terceros. William Harris demostró en *War and Imperialism in Republican Rome* (1979) que la sociedad romana tenía incentivos estructurales para la guerra: el prestigio militar era requisito de la carrera política, el triunfo y el botín enriquecían a los generales, y las campañas anuales eran la norma y no la excepción.\n\nLas consecuencias internas fueron desestabilizadoras. La conquista trajo esclavos en masa —cientos de miles— que sustituyeron mano de obra libre; permitió a los senadores acumular latifundios trabajados por esclavos; arruinó a los pequeños propietarios, ausentes en campañas de años; y creó una plebe urbana sin tierra ni empleo estable. La riqueza provincial, gestionada por gobernadores con escasísimo control, generó además una corrupción de escala nueva.","textEso":"Roma pasó de dominar una región de Italia a controlar todo el Mediterráneo en menos de dos siglos. Las tres guerras púnicas contra Cartago fueron decisivas, y Aníbal estuvo cerca de ganar la segunda. Después vinieron Grecia, Macedonia y Asia Menor. Su método tenía dos claves: un ejército de ciudadanos que podía perder batallas y seguir reclutando, y un sistema de alianzas que obligaba a los vencidos a aportar soldados, de modo que cada victoria hacía a Roma más fuerte.","textBachillerato":"Entre el siglo III y el I a. C. Roma pasa de potencia itálica a dueña del Mediterráneo. Las guerras púnicas son el punto de inflexión: la segunda, con Aníbal operando en Italia durante quince años y la derrota romana de Cannas, estuvo cerca de acabar con Roma. Después llegan Macedonia, Grecia, Asia Menor e Hispania, esta última en una conquista larga y costosa.\n\nLos mecanismos importan más que las fechas. Primero, un sistema de alianzas itálicas que no exigía tributo sino soldados, de modo que cada incorporación aumentaba la capacidad militar: Roma podía perder ejércitos enteros y reclutar otros. Segundo, una élite cuyo prestigio dependía del mando militar, lo que generaba un impulso expansivo continuo. Si la expansión fue defensiva, como sostenía la tradición romana, o estructuralmente agresiva, sigue siendo objeto de discusión; los datos sobre botín, esclavos y carreras políticas apuntan más a lo segundo.","callout":null},{"type":"section","title":"La crisis: de los Gracos a Sila","text":"En 133 a. C., el tribuno Tiberio Graco propuso aplicar un límite legal existente pero incumplido sobre la ocupación de tierra pública, y repartir el excedente entre ciudadanos sin tierra. El objetivo era militar además de social: solo los propietarios podían ser reclutados, así que la desaparición del campesinado amenazaba el reclutamiento.\n\nLa reacción del Senado fue brutal. Tiberio fue asesinado junto a centenares de partidarios; su hermano Cayo, tras un programa más amplio, murió en circunstancias similares en 121 a. C. Ese episodio inauguró el uso sistemático de la violencia política en Roma y dividió la vida pública entre populares —quienes buscaban apoyo en las asambleas y en la plebe— y optimates —quienes defendían la primacía del Senado—. Conviene subrayar que no eran partidos ni ideologías, sino métodos de acción política.\n\nCayo Mario abrió la brecha decisiva. Al reclutar proletarios sin propiedad, resolvió el problema de efectivos pero creó un ejército cuyos soldados no esperaban tierra del Estado, sino de su general. La lealtad militar se personalizó. A partir de ahí, quien mandaba legiones disponía de un instrumento político, y las guerras civiles se volvieron posibles.\n\nLa Guerra Social (91-88 a. C.) enfrentó a Roma con sus aliados itálicos, que exigían la ciudadanía tras siglos aportando tropas. Roma perdió militarmente el conflicto en buena medida y lo resolvió concediendo lo que se le pedía: la ciudadanía se extendió a toda Italia al sur del Po. Fue una integración forzada por la guerra, no una generosidad.\n\nSila llevó la lógica hasta el final: en 88 a. C. marchó con sus legiones sobre Roma, algo hasta entonces impensable; en 82 a. C. se hizo nombrar dictador sin límite temporal e instauró las proscripciones, listas públicas de enemigos cuya muerte era recompensada y cuyos bienes se confiscaban. Reforzó el Senado y limitó el tribunado, y después se retiró. Su precedente —tomar el poder por las armas y reorganizar el Estado— resultó más duradero que sus reformas.","textEso":"La conquista enriqueció a unos pocos y arruinó a muchos. Los grandes propietarios compraron tierras trabajadas por esclavos baratos traídos de las guerras, y el pequeño campesino, que pasaba años movilizado, no podía competir. Los hermanos Graco intentaron repartir tierra pública y los dos fueron asesinados. A partir de ahí la violencia entró en la política: Mario abrió el ejército a los sin tierra, que pasaron a depender de su general y no del Estado, y Sila tomó Roma con sus propias legiones.","textBachillerato":"La conquista desestabilizó la sociedad que la había hecho posible. La entrada masiva de esclavos abarató la mano de obra y favoreció la gran propiedad, mientras el pequeño propietario, movilizado durante campañas cada vez más largas y lejanas, perdía su explotación. El resultado fue concentración de tierra y una población urbana sin recursos en Roma.\n\nLos Gracos plantearon el reparto del ager publicus y ambos murieron violentamente, en 133 y 121 a. C.: la violencia política quedó normalizada. La reforma de Mario, al admitir en las legiones a ciudadanos sin propiedad, creó ejércitos cuyo vínculo era con el general que los pagaba y les prometía tierras, no con la República. Sila extrajo la conclusión y ocupó Roma con sus legiones, instaurando una dictadura y proscripciones. A partir de ahí la pregunta ya no era si el sistema cambiaría, sino cómo.","callout":"Populares y optimates no eran partidos con programa ni afiliación estable. Un mismo aristócrata podía usar métodos populares en una coyuntura y defender al Senado en otra: eran estrategias, no ideologías."},{"type":"section","title":"El derrumbe final y la cuestión de por qué","text":"La generación siguiente actuó ya sobre un sistema descompuesto. Pompeyo obtuvo mandos extraordinarios de amplitud inédita; Craso aportó una fortuna colosal; César combinó ambición, capacidad militar y apoyo popular. El acuerdo privado de los tres en 60 a. C. —el llamado primer triunvirato— no fue una institución, sino un pacto para repartirse el control de las elecciones y los mandos, y muestra hasta qué punto las instituciones habían dejado de decidir.\n\nLa conquista de la Galia dio a César una clientela militar, un prestigio inmenso y un botín enorme. Cuando el Senado le exigió licenciar sus tropas, cruzó el Rubicón (49 a. C.). Tras vencer, acumuló cargos, se hizo nombrar dictador perpetuo y aceptó honores que evocaban la realeza y el culto divino. Fue asesinado en 44 a. C. por un grupo de senadores que decían restaurar la República, y cuyo golpe solo produjo trece años más de guerra civil.\n\nLa derrota de Marco Antonio y Cleopatra en Accio (31 a. C.) dejó a Octavio como único poder. En 27 a. C. devolvió formalmente sus poderes al Senado y recibió a cambio el nombre de Augusto y una posición que conservaba todas las apariencias republicanas: magistraturas tradicionales, Senado en funcionamiento, ausencia de título real. Tácito resumió la operación con una frase demoledora: conservó los nombres de las cosas y cambió su sustancia.\n\nSobre las causas del derrumbe hay varias líneas de explicación. Una subraya los factores socioeconómicos: la ruina del campesinado, la esclavitud masiva y la concentración de la tierra. Otra insiste en el desajuste institucional: instituciones diseñadas para una ciudad-Estado gobernando un imperio mediterráneo, sin administración profesional, sin control efectivo de los gobernadores y con magistraturas anuales incompatibles con guerras de años. Una tercera, desarrollada por Ronald Syme en *The Roman Revolution* (1939), analiza el cambio como sustitución de una oligarquía por otra mediante la violencia y el clientelismo, y desmonta la retórica de la restauración augústea.\n\nLa lectura más aceptada hoy combina las tres y añade un factor cultural: la competencia aristocrática por el honor, que había sido el motor de la expansión, dejó de tener límites eficaces cuando los premios se volvieron desmesurados y los ejércitos, personales. La República no fue derribada por enemigos externos ni por una revolución popular, sino por la propia clase que la dirigía.","textEso":"El final fue una sucesión de guerras civiles entre generales con ejércitos leales a ellos: César contra Pompeyo, y después Octavio contra Marco Antonio. César fue asesinado en el 44 a. C. por senadores que querían salvar la República, y el resultado fue justo el contrario: trece años más de guerra y la victoria de Octavio, que se convirtió en Augusto. La causa de fondo no fue la ambición de un hombre: un sistema pensado para gobernar una ciudad no servía para administrar un imperio.","textBachillerato":"El último medio siglo republicano es una secuencia de pactos entre hombres fuertes y guerras civiles: el acuerdo de César, Pompeyo y Craso; la guerra entre César y Pompeyo; la dictadura y el asesinato de César en 44 a. C.; y el enfrentamiento final entre Octavio y Marco Antonio, resuelto en Accio en 31 a. C. El asesinato de César, pensado para restaurar la República, la liquidó definitivamente.\n\nSobre las causas hay varias lecturas. Una atribuye el derrumbe a la ambición personal de una generación de líderes. Otra señala la contradicción estructural: instituciones diseñadas para una ciudad-Estado gobernando un imperio, sin administración provincial profesional, sin ejército estatal desvinculado de sus jefes y sin mecanismo para integrar políticamente a Italia y las provincias. La segunda explica mejor por qué el sistema no se recuperó ni siquiera cuando los protagonistas desaparecieron, y por qué el régimen de Augusto, que mantuvo las formas republicanas, fue aceptado sin apenas resistencia.","callout":null},{"type":"concepts","items":[{"term":"Mos maiorum","definition":"Costumbre de los antepasados: conjunto de normas no escritas que hacía de constitución romana."},{"term":"Cursus honorum","definition":"Orden legal de las magistraturas, con edades mínimas e intervalos obligatorios entre cargos."},{"term":"Imperium","definition":"Poder de mando militar y jurisdiccional que ostentaban cónsules, pretores y dictadores."},{"term":"Intercessio","definition":"Derecho de veto de los tribunos de la plebe frente a actos de cualquier magistrado."},{"term":"Sacrosanctitas","definition":"Inviolabilidad religiosa del tribuno de la plebe: agredirlo suponía maldición y muerte impune."},{"term":"Clientela","definition":"Vínculo asimétrico y hereditario entre patrono y cliente. Base real de la política romana."},{"term":"Nobilitas","definition":"Élite patricio-plebeya formada por familias que habían alcanzado el consulado."},{"term":"Homo novus","definition":"Primer miembro de una familia en llegar al consulado. Caso excepcional, como Cicerón."},{"term":"Ager publicus","definition":"Tierra pública conquistada, ocupada de hecho por grandes propietarios pese a los límites legales."},{"term":"Populares / optimates","definition":"Métodos de acción política —apoyo en las asambleas o en el Senado—, no partidos ni ideologías."},{"term":"Proscripción","definition":"Lista pública de enemigos cuya muerte se recompensaba y cuyos bienes se confiscaban. Instaurada por Sila."},{"term":"Socii","definition":"Aliados itálicos obligados a aportar tropas sin ser ciudadanos. Origen de la Guerra Social."}]},{"type":"debates","items":[{"question":"¿Fue el imperialismo romano defensivo o estructuralmente agresivo?","positions":[{"school":"Imperialismo defensivo (Mommsen; tradición apoyada en las fuentes romanas)","argument":"Roma habría entrado en guerra siempre provocada, aplicando el procedimiento del bellum iustum y respondiendo a amenazas o a peticiones de aliados. La expansión sería un resultado no buscado de una política de seguridad."},{"school":"Agresividad estructural (Harris, 1979)","argument":"El prestigio militar era requisito del ascenso político, el botín enriquecía a generales y soldados, y la guerra era la actividad normal de casi todos los años. Los incentivos internos empujaban a la expansión con independencia de las provocaciones externas."}],"state":"La tesis de Harris se ha impuesto mayoritariamente en su núcleo: la sociedad romana estaba organizada para la guerra. Se discute cuánta planificación consciente hubo y cuánto peso tuvieron los intereses económicos frente a los del honor aristocrático."},{"question":"¿Fue la República romana en algún sentido democrática?","positions":[{"school":"Elementos democráticos reales (Millar, 1998)","argument":"El pueblo reunido en asamblea elegía magistrados y aprobaba leyes; los políticos debían persuadirlo en la contio. La política romana se hacía en público y la retórica popular tenía efectos, lo que impide reducirla a mera fachada oligárquica."},{"school":"Oligarquía con consentimiento (Mouritsen; tradición de Gelzer y Syme)","argument":"La estructura de voto por centurias favorecía a los ricos, la asistencia efectiva a las asambleas era baja, no existía debate ni enmienda en la votación, y las clientelas condicionaban el resultado. El pueblo ratificaba decisiones tomadas en otro sitio."}],"state":"El debate abierto por Millar renovó el campo. La posición dominante reconoce una dimensión pública y persuasiva de la política romana, sin aceptar que existiera soberanía popular efectiva: se habla de «oligarquía que necesitaba legitimación popular»."},{"question":"¿Por qué cayó la República?","positions":[{"school":"Explicación socioeconómica","argument":"La conquista arruinó al pequeño campesinado, sustituyó trabajo libre por esclavo y concentró la tierra. Sin propietarios no había reclutas ni base social del régimen, y el conflicto por la tierra se hizo insoluble."},{"school":"Desajuste institucional","argument":"Instituciones de ciudad-Estado gobernaban un imperio: magistraturas anuales frente a guerras de años, sin administración profesional ni control de los gobernadores. Los mandos extraordinarios eran la única solución práctica y a la vez el instrumento de su destrucción."},{"school":"Revolución de la clase dirigente (Syme, 1939)","argument":"Lo ocurrido fue la sustitución de una oligarquía por otra mediante violencia, clientelismo y propaganda. La «restauración» augústea fue una operación retórica sobre un cambio de régimen efectivo."}],"state":"Se prefieren hoy explicaciones combinadas. Se subraya además un factor cultural: la competencia aristocrática por el honor perdió sus límites cuando los premios se hicieron desmesurados y los ejércitos, personales."}]},{"type":"timeline","items":[{"date":"509 a. C.","event":"Fecha tradicional de la expulsión del último rey y fundación de la República."},{"date":"494 a. C.","event":"Primera secesión de la plebe; creación del tribunado."},{"date":"451–450 a. C.","event":"Ley de las Doce Tablas: primer derecho romano escrito."},{"date":"367 a. C.","event":"Leyes Licinias-Sextias: acceso plebeyo al consulado."},{"date":"287 a. C.","event":"Lex Hortensia: los plebiscitos obligan a todo el pueblo. Fin del conflicto de órdenes."},{"date":"264–241 a. C.","event":"Primera guerra púnica; Roma se convierte en potencia naval."},{"date":"218–201 a. C.","event":"Segunda guerra púnica: Aníbal en Italia; victoria de Escipión en Zama."},{"date":"146 a. C.","event":"Destrucción de Cartago y de Corinto. Hegemonía mediterránea."},{"date":"133 a. C.","event":"Tribunado y asesinato de Tiberio Graco. Comienza la crisis."},{"date":"107–100 a. C.","event":"Reforma militar de Mario: reclutamiento de proletarios."},{"date":"91–88 a. C.","event":"Guerra Social; extensión de la ciudadanía a los itálicos."},{"date":"82–79 a. C.","event":"Dictadura de Sila y proscripciones."},{"date":"60 a. C.","event":"Primer triunvirato: César, Pompeyo y Craso."},{"date":"49–45 a. C.","event":"Guerra civil; César dictador."},{"date":"44 a. C.","event":"Asesinato de César en los idus de marzo."},{"date":"31–27 a. C.","event":"Accio y establecimiento del principado de Augusto."}]},{"type":"sources","items":[{"author":"Polibio","title":"Historias, libro VI","year":"c. 140 a. C.","kind":"primaria","note":"Análisis de la constitución mixta romana por un testigo griego contemporáneo."},{"author":"Tito Livio","title":"Ab Urbe condita","year":"c. 27 a. C.–17 d. C.","kind":"primaria","note":"Relato monumental desde los orígenes. Fuente esencial y a la vez construcción ideológica augústea."},{"author":"Salustio","title":"La conjuración de Catilina; La guerra de Yugurta","year":"c. 42–40 a. C.","kind":"primaria","note":"Análisis contemporáneo de la corrupción de la élite republicana."},{"author":"Cicerón","title":"Cartas a Ático; discursos","year":"68–43 a. C.","kind":"primaria","note":"Correspondencia privada excepcional: la política republicana vista desde dentro y en tiempo real."},{"author":"Plutarco","title":"Vidas paralelas","year":"c. 100 d. C.","kind":"primaria","note":"Biografías de los Gracos, Mario, Sila, Pompeyo y César. Interés moral más que analítico."},{"author":"Ronald Syme","title":"The Roman Revolution","year":"1939","kind":"estudio","note":"Analiza el ascenso de Augusto como sustitución de oligarquías. Obra fundacional de la prosopografía romana."},{"author":"William V. Harris","title":"War and Imperialism in Republican Rome, 327–70 BC","year":"1979","kind":"estudio","note":"Demuele la tesis del imperialismo defensivo."},{"author":"Fergus Millar","title":"The Crowd in Rome in the Late Republic","year":"1998","kind":"estudio","note":"Reabre el debate sobre los elementos democráticos de la República."},{"author":"Henrik Mouritsen","title":"Plebs and Politics in the Late Roman Republic","year":"2001","kind":"estudio","note":"Respuesta crítica a Millar sobre la participación popular efectiva."},{"author":"Mary Beard","title":"SPQR: A History of Ancient Rome","year":"2015","kind":"estudio","note":"Síntesis reciente muy atenta a los problemas de fuentes y a la vida de la gente común."}]},{"type":"images","items":[{"src":"/img/roma-republica/portada.jpg","alt":"Pintura del siglo XIX con Cicerón de pie ante el Senado romano mientras Catilina aparece aislado en un banco","width":1200,"height":748,"role":"portada","caption":"Cicerón denuncia a Catilina, según Cesare Maccari (1888). Es una reconstrucción del XIX, no un documento antiguo.","author":"Cesare Maccari","title":"Cicerone denuncia Catilina Cicero Denounces Catiline","year":"1889","source":"Wikimedia Commons","license":"Public domain","url":"https://commons.wikimedia.org/wiki/File:Maccari-Cicero.jpg"},{"src":"/img/roma-republica/loba.jpg","alt":"Escultura en bronce de una loba en tensión con dos niños desnudos amamantándose bajo su vientre","width":1200,"height":900,"role":"figura","section":0,"caption":"La loba capitolina. El bronce es medieval o antiguo según el análisis que se acepte, y los gemelos son un añadido renacentista: la imagen fundacional de Roma es ella misma un problema de fuentes.","author":"Benutzer:Wolpertinger on WP de","title":"She-wolf suckles Romulus and Remus","year":"sin fecha","source":"Wikimedia Commons","license":"Public domain","url":"https://commons.wikimedia.org/wiki/File:She-wolf_suckles_Romulus_and_Remus.jpg"},{"src":"/img/roma-republica/foro.jpg","alt":"Ruinas de columnas, arcos y basamentos de mármol repartidos por una explanada rodeada de colinas","width":1200,"height":589,"role":"figura","section":1,"caption":"El Foro Romano. Aquí se reunían los comicios, se administraba justicia y se hablaba al pueblo: la constitución republicana era un espacio antes que un texto.","author":"Stefan Bauer, http://www.ferras.at","title":"Forum Romanum Rom","year":"2005","source":"Wikimedia Commons","license":"CC BY-SA 2.5","url":"https://commons.wikimedia.org/wiki/File:Forum_Romanum_Rom.jpg"},{"src":"/img/roma-republica/vercingetorix.jpg","alt":"Pintura de un guerrero a caballo arrojando sus armas ante un general romano sentado y rodeado de su estado mayor","width":1200,"height":800,"role":"figura","section":5,"caption":"Vercingétorix se rinde ante César, según Lionel Royer (1899). Es una escena patriótica francesa del XIX, no un documento antiguo: así se leía la conquista de la Galia mil novecientos años después.","author":"Lionel Royer","title":"Vercingetorix jette ses armes aux pieds de Jules César Vercingetorix throws down his arms at the feet of Julius Caesar","year":"1899","source":"Wikimedia Commons","license":"Public domain","url":"https://commons.wikimedia.org/wiki/File:Lionel_Royer_-_Vercingetorix_Throwing_down_His_Weapons_at_the_feet_of_Julius_Caesar.jpg"}]}]'::jsonb, 0, true
